"""Editorial content for the Persian guide. No scraped reviews or unverified operator claims."""
PAGES = {}

def page(slug, title, description, category, intro, takeaway, sections, faq=(), related=(), image="editorial", kind="Article", sources=()):
    PAGES[slug] = dict(slug=slug,title=title,description=description,category=category,intro=intro,takeaway=takeaway,sections=sections,faq=faq,related=related,image=image,kind=kind,sources=sources)

def section(title, *paragraphs, bullets=(), table=None, extra=""):
    return dict(title=title,paragraphs=paragraphs,bullets=bullets,table=table,extra=extra)

