 [
 section("ظاهر بازی با منطق نتیجه فرق دارد","ممکن است نتیجه ابتدا در سرور تعیین شود و سپس مرورگر آن را نمایش دهد. در نسخه‌ای دیگر، ورودی کاربر بخشی از محاسبه باشد. برای تشخیص این دو، توضیح سازنده و نسخه بازی لازم است.",
 "کند یا تند شدن انیمیشن، به خودی خود رابطه‌ای با احتمال برد ثابت نمی‌کند. خطای ارتباط و زمان ثبت ورودی نیز باید از الگوریتم تولید نتیجه تفکیک شود."),
 section("هش با رمز قابل برگشت یکسان نیست","تابع هش ورودی را به یک خروجی مشخص تبدیل می‌کند. مقایسه هش یک ورودی افشاشده با خروجی قبلی، یک کاربرد رایج است. این مقایسه با استخراج قطعی ورودی پنهان از هش تفاوت دارد.",
 "در سامانه‌های قابل بررسی، علاوه بر تابع، ترتیب ورودی‌ها، شمارنده و روش تبدیل عددها مهم‌اند. نام یک تابع مشهور بدون انتشار بقیه مراحل، توضیح کامل یک بازی نیست."),
 section("چه مدرکی برای ادعای پیش‌بینی لازم است؟","برای بررسی یک ادعا، شرایط آزمون باید از قبل روشن باشد. فقط نمایش دورهای موفق، امکان سنجش شکست‌ها یا انتخاب گزینشی نمونه‌ها را از بین می‌برد.",
 bullets=["نسخه بازی و داده مورد استفاده مشخص باشد.","پیش‌بینی پیش از اعلام نتیجه ثبت شود.","همه نمونه‌ها، از جمله خطاها، قابل بررسی باشند.","آزمون مستقل و روش قابل بازتولید وجود داشته باشد."]),
 section("نشانه‌های ابزار مشکوک","درخواست رمز، کد پیامک، دسترسی کنترل دستگاه یا عبارت بازیابی برای یک ربات پیش‌بینی، نشانه‌ای برای توقف است. پرداخت بیشتر برای «فعال‌سازی برداشت» نیز باید جداگانه بررسی شود.",
 "اگر ابزار ادعا می‌کند با افزایش مبلغ پس از هر باخت، ضرر قطعاً جبران می‌شود، محدودیت سرمایه و سقف مبلغ را نادیده گرفته است. هیچ زنجیره مبلغی نتیجه آینده را تضمین نمی‌کند.")
 ],
